package com.ecole.gestion_scolaire.transport.service;
import com.ecole.gestion_scolaire.transport.entity.*; import com.ecole.gestion_scolaire.transport.repository.*; import com.ecole.gestion_scolaire.transport.dto.TransportDtos.*;
import com.ecole.gestion_scolaire.registration.repository.StudentEnrollmentRepository; import com.ecole.gestion_scolaire.finance.repository.*; import com.ecole.gestion_scolaire.finance.entity.*;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.time.*; import java.math.*;
@Service @Transactional public class TransportService {
 private final TransportVehicleRepository vehicles; private final TransportDriverRepository drivers; private final TransportRouteRepository routes; private final TransportStopRepository stops; private final StudentTransportAssignmentRepository assignments; private final StudentEnrollmentRepository enrollments; private final FeeTypeRepository feeTypes; private final StudentChargeRepository charges;
 public TransportService(TransportVehicleRepository a,TransportDriverRepository b,TransportRouteRepository c,TransportStopRepository d,StudentTransportAssignmentRepository e,StudentEnrollmentRepository f,FeeTypeRepository g,StudentChargeRepository h){vehicles=a;drivers=b;routes=c;stops=d;assignments=e;enrollments=f;feeTypes=g;charges=h;}
 public List<TransportVehicle> vehicles(){return vehicles.findAll();} public TransportVehicle saveVehicle(Long id,VehicleRequest r){var x=id==null?new TransportVehicle():vehicles.findById(id).orElseThrow();x.code=r.code();x.registrationNumber=r.registrationNumber();x.brand=r.brand();x.model=r.model();x.capacity=r.capacity();x.insuranceExpiry=r.insuranceExpiry();x.technicalInspectionExpiry=r.technicalInspectionExpiry();x.status=r.status()==null?"ACTIVE":r.status();x.notes=r.notes();return vehicles.save(x);}
 public List<TransportDriver> drivers(){return drivers.findAll();} public TransportDriver saveDriver(Long id,DriverRequest r){var x=id==null?new TransportDriver():drivers.findById(id).orElseThrow();x.lastName=r.lastName();x.firstName=r.firstName();x.phone=r.phone();x.licenseNumber=r.licenseNumber();x.licenseExpiry=r.licenseExpiry();x.status=r.status()==null?"ACTIVE":r.status();x.notes=r.notes();return drivers.save(x);}
 public List<TransportRoute> routes(Long year){return routes.findAll().stream().filter(x->year==null||year.equals(x.schoolYearId)).toList();} public TransportRoute saveRoute(Long id,RouteRequest r){if(r.vehicleId()!=null&&!vehicles.existsById(r.vehicleId()))throw new IllegalArgumentException("Véhicule introuvable");if(r.driverId()!=null&&!drivers.existsById(r.driverId()))throw new IllegalArgumentException("Chauffeur introuvable");var x=id==null?new TransportRoute():routes.findById(id).orElseThrow();x.schoolYearId=r.schoolYearId();x.code=r.code();x.name=r.name();x.vehicleId=r.vehicleId();x.driverId=r.driverId();x.morningDeparture=r.morningDeparture();x.returnDeparture=r.returnDeparture();x.active=r.active()==null||r.active();x.notes=r.notes();return routes.save(x);}
 public List<TransportStop> stops(Long routeId){return stops.findAll().stream().filter(x->routeId.equals(x.routeId)).sorted(Comparator.comparing(x->x.stopOrder)).toList();} public TransportStop saveStop(Long routeId,Long id,StopRequest r){if(!routes.existsById(routeId))throw new IllegalArgumentException("Circuit introuvable");var x=id==null?new TransportStop():stops.findById(id).orElseThrow();x.routeId=routeId;x.name=r.name();x.stopOrder=r.stopOrder();x.morningTime=r.morningTime();x.returnTime=r.returnTime();x.address=r.address();x.latitude=r.latitude();x.longitude=r.longitude();x.active=r.active()==null||r.active();return stops.save(x);}
 public List<StudentTransportAssignment> assignments(Long enrollmentId){return assignments.findAll().stream().filter(x->enrollmentId==null||enrollmentId.equals(x.studentEnrollmentId)).toList();}
 public StudentTransportAssignment assign(AssignmentRequest r){var en=enrollments.findById(r.studentEnrollmentId()).orElseThrow(()->new IllegalArgumentException("Scolarisation introuvable"));var route=routes.findById(r.routeId()).orElseThrow(()->new IllegalArgumentException("Circuit introuvable"));var stop=stops.findById(r.stopId()).orElseThrow(()->new IllegalArgumentException("Arrêt introuvable"));if(!Objects.equals(stop.routeId,route.id))throw new IllegalArgumentException("L'arrêt n'appartient pas au circuit");if(!Objects.equals(en.getSchoolYearId(),route.schoolYearId))throw new IllegalArgumentException("Circuit et élève doivent appartenir à la même année scolaire");if(!Set.of("ROUND_TRIP","OUTBOUND_ONLY","RETURN_ONLY").contains(r.serviceType()))throw new IllegalArgumentException("Type de service invalide");var x=new StudentTransportAssignment();x.studentEnrollmentId=r.studentEnrollmentId();x.routeId=r.routeId();x.stopId=r.stopId();x.serviceType=r.serviceType();x.monthlyFee=r.monthlyFee();x.startDate=r.startDate();x.endDate=r.endDate();x.status="ACTIVE";return assignments.save(x);}
 public StudentTransportAssignment close(Long id,LocalDate end){var x=assignments.findById(id).orElseThrow();x.endDate=end==null?LocalDate.now():end;x.status="ENDED";return assignments.save(x);}
 public int generateCharges(Long assignmentId){var a=assignments.findById(assignmentId).orElseThrow();var en=enrollments.findById(a.studentEnrollmentId).orElseThrow();var ft=feeTypes.findByCodeIgnoreCase("TRANSPORT").orElseThrow();LocalDate start=a.startDate.withDayOfMonth(1), schoolEnd=LocalDate.of(en.getEnrollmentDate().getYear()+1,6,30);LocalDate end=a.endDate==null?schoolEnd:a.endDate;int count=0;for(LocalDate m=start;!m.isAfter(end);m=m.plusMonths(1)){if(m.getMonthValue()==7||m.getMonthValue()==8)continue;if(charges.existsByStudentEnrollmentIdAndFeeTypeIdAndBillingPeriodStartAndStatusNot(en.getId(),ft.getId(),m,"CANCELLED"))continue;var c=new StudentCharge();c.setStudentEnrollmentId(en.getId());c.setFeeTypeId(ft.getId());c.setLabel("Transport scolaire - "+String.format("%02d/%d",m.getMonthValue(),m.getYear()));c.setOriginalAmount(a.monthlyFee);c.setDiscountAmount(BigDecimal.ZERO);c.setFinalAmount(a.monthlyFee);c.setDueDate(m);c.setBillingPeriodStart(m);c.setBillingPeriodEnd(m.withDayOfMonth(m.lengthOfMonth()));c.setStatus(a.monthlyFee.signum()==0?"PAID":"DUE");charges.save(c);count++;}return count;}
}
